#include <inttypes.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>

#if CHAR_BIT != 8
#error "This four-octet format requires 8-bit C bytes"
#endif
#ifndef UINT32_MAX
#error "This example requires an exact 32-bit unsigned integer type"
#endif

static void encode_be32(uint32_t value, unsigned char out[4]) {
    out[0] = (unsigned char)(value >> 24);
    out[1] = (unsigned char)(value >> 16);
    out[2] = (unsigned char)(value >> 8);
    out[3] = (unsigned char)value;
}

static uint32_t decode_be32(const unsigned char in[4]) {
    return ((uint32_t)in[0] << 24) |
           ((uint32_t)in[1] << 16) |
           ((uint32_t)in[2] << 8) |
           (uint32_t)in[3];
}

int main(void) {
    const uint32_t original = UINT32_C(0x1234ABCD);
    unsigned char bytes[4];
    encode_be32(original, bytes);
    printf("bytes=%02X %02X %02X %02X\n",
           (unsigned)bytes[0], (unsigned)bytes[1],
           (unsigned)bytes[2], (unsigned)bytes[3]);
    printf("decoded=%" PRIu32 "\n", decode_be32(bytes));
    return 0;
}
